import{_ as t,o as i,c as a,ao as s}from"./chunks/framework.CwrF1Ikc.js";const d="/WaterLily-Benchmarks/dev/assets/tgv.BnvzEEET.png",o="/WaterLily-Benchmarks/dev/assets/tgv-periodic.B-j3W6_o.png",r="/WaterLily-Benchmarks/dev/assets/sphere.D7LbTFap.png",c="/WaterLily-Benchmarks/dev/assets/sphere-biotsavart.TOJS2tPc.png",n="/WaterLily-Benchmarks/dev/assets/cylinder.D9lsV566.png",l="/WaterLily-Benchmarks/dev/assets/cylinder-biotsavart.CHAM3iyI.png",h="/WaterLily-Benchmarks/dev/assets/donut.GXaq1PsG.png",p="/WaterLily-Benchmarks/dev/assets/jelly-biotsavart.CEiuSahY.png",x=JSON.parse('{"title":"Cases and checkpoints","description":"","frontmatter":{},"headers":[],"relativePath":"cases.md","filePath":"cases.md","lastUpdated":null}'),g={name:"cases.md"};function y(k,e,f,m,u,v){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="Cases-and-checkpoints" tabindex="-1">Cases and checkpoints <a class="header-anchor" href="#Cases-and-checkpoints" aria-label="Permalink to &quot;Cases and checkpoints {#Cases-and-checkpoints}&quot;">​</a></h1><p>Each case is a function in <a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/blob/main/src/cases.jl" target="_blank" rel="noreferrer"><code>src/cases.jl</code></a> that returns a WaterLily <code>Simulation</code> for a size <code>log2p</code>, a backend and a float type. The <code>-biotsavart</code> cases use the open boundaries of <a href="https://github.com/WaterLily-jl/BiotSavartBCs.jl" target="_blank" rel="noreferrer">BiotSavartBCs.jl</a> instead of WaterLily&#39;s default ones, and solve the pressure Poisson equation through its <code>mom_project!</code> (see <a href="./biotsavart">BiotSavartBCs changes</a>).</p><table tabindex="0"><thead><tr><th style="text-align:right;">Case</th><th style="text-align:right;">Flow</th><th style="text-align:right;">Grid (cells), <code>n = 2^log2p</code></th><th style="text-align:right;">Default <code>-p</code></th><th style="text-align:right;">Checkpoints</th></tr></thead><tbody><tr><td style="text-align:right;"><code>tgv</code></td><td style="text-align:right;">Taylor-Green vortex, Re = 1600, symmetry planes</td><td style="text-align:right;"><code>n × n × n</code></td><td style="text-align:right;"><code>6,7</code></td><td style="text-align:right;">6, 7, 8</td></tr><tr><td style="text-align:right;"><code>tgv-periodic</code></td><td style="text-align:right;"><code>tgv</code>, periodic in every direction</td><td style="text-align:right;"><code>n × n × n</code></td><td style="text-align:right;"><code>6,7</code></td><td style="text-align:right;">6, 7</td></tr><tr><td style="text-align:right;"><code>sphere</code></td><td style="text-align:right;">sphere of diameter <code>n</code>, Re = 3700, convective exit</td><td style="text-align:right;"><code>16n × 6n × 6n</code></td><td style="text-align:right;"><code>3,4</code></td><td style="text-align:right;">3, 4, 5</td></tr><tr><td style="text-align:right;"><code>sphere-biotsavart</code></td><td style="text-align:right;"><code>sphere</code> with Biot-Savart boundaries</td><td style="text-align:right;"><code>16n × 6n × 6n</code></td><td style="text-align:right;"><code>3,4</code></td><td style="text-align:right;">3, 4</td></tr><tr><td style="text-align:right;"><code>cylinder</code></td><td style="text-align:right;">cylinder of diameter <code>n</code> heaving across the flow, Re = 1000, periodic span</td><td style="text-align:right;"><code>9n × 6n × 2n</code></td><td style="text-align:right;"><code>4,5</code></td><td style="text-align:right;">4, 5</td></tr><tr><td style="text-align:right;"><code>cylinder-biotsavart</code></td><td style="text-align:right;"><code>cylinder</code> with Biot-Savart boundaries</td><td style="text-align:right;"><code>9n × 6n × 2n</code></td><td style="text-align:right;"><code>4,5</code></td><td style="text-align:right;">4, 5</td></tr><tr><td style="text-align:right;"><code>donut</code></td><td style="text-align:right;">torus of radius <code>n/4</code>, Re = 1000</td><td style="text-align:right;"><code>2n × n × n</code></td><td style="text-align:right;"><code>5,6</code></td><td style="text-align:right;">5, 6</td></tr><tr><td style="text-align:right;"><code>jelly-biotsavart</code></td><td style="text-align:right;">swimming jellyfish, Re = 500, a quarter of the domain with two symmetry planes</td><td style="text-align:right;"><code>n × n × 4n</code></td><td style="text-align:right;"><code>5,6</code></td><td style="text-align:right;">5, 6, 7</td></tr></tbody></table><p>The bodies of <code>cylinder</code>, <code>cylinder-biotsavart</code> and <code>jelly-biotsavart</code> move, so they are measured again at every step.</p><div style="display:grid;grid-template-columns:repeat(auto-fill, minmax(220px, 1fr));gap:12px;margin:16px 0;"><figure style="margin:0;"><img src="'+d+'" alt="tgv" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>tgv</code></figcaption></figure><figure style="margin:0;"><img src="'+o+'" alt="tgv-periodic" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>tgv-periodic</code></figcaption></figure><figure style="margin:0;"><img src="'+r+'" alt="sphere" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>sphere</code></figcaption></figure><figure style="margin:0;"><img src="'+c+'" alt="sphere-biotsavart" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>sphere-biotsavart</code></figcaption></figure><figure style="margin:0;"><img src="'+n+'" alt="cylinder" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>cylinder</code></figcaption></figure><figure style="margin:0;"><img src="'+l+'" alt="cylinder-biotsavart" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>cylinder-biotsavart</code></figcaption></figure><figure style="margin:0;"><img src="'+h+'" alt="donut" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>donut</code></figcaption></figure><figure style="margin:0;"><img src="'+p+`" alt="jelly-biotsavart" style="width:100%;border-radius:6px;background:#fff;"><figcaption style="text-align:center;font-size:0.85em;"><code>jelly-biotsavart</code></figcaption></figure></div><p><em>Vorticity of the developed flow in the largest checkpoint of each case.</em></p><h2 id="Developed-flow-checkpoints" tabindex="-1">Developed-flow checkpoints <a class="header-anchor" href="#Developed-flow-checkpoints" aria-label="Permalink to &quot;Developed-flow checkpoints {#Developed-flow-checkpoints}&quot;">​</a></h2><p>By default every benchmark starts from a <em>developed</em> flow, so that it times the steady cost of a step rather than the startup transient. The flows are stored as <code>checkpoints/&lt;case&gt;_&lt;log2p&gt;_&lt;ftype&gt;.jld2</code>: each case is advanced to a developed state (to <code>tU/L = 10</code> for the <code>tgv</code> cases and 100 for the bluff bodies, and for 10 swimming cycles for <code>jelly-biotsavart</code>, as set in <code>develop_time</code> in <code>src/util.jl</code>) and saved. A run with a size or float type that has no checkpoint stops with an error. <code>benchmark.sh -dev &quot;&quot;</code> times the transient instead.</p><p>The checkpoints are git-LFS files. In a clone made with <code>GIT_LFS_SKIP_SMUDGE=1</code>, as in CI, they are small pointers, and <code>benchmark.sh</code> downloads the ones a sweep needs with <code>git lfs pull</code>.</p><p><a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/blob/main/develop.jl" target="_blank" rel="noreferrer"><code>develop.jl</code></a> makes the checkpoints, and <a href="https://github.com/WaterLily-jl/WaterLily-Benchmarks/blob/main/visualize.jl" target="_blank" rel="noreferrer"><code>visualize.jl</code></a> renders their vorticity into <code>checkpoints/viz/</code> to check them by eye (<code>Float64</code> cases are skipped; it uses GLMakie from the plotting environment):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # every case at its checkpoint sizes, Float32</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cases=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[&quot;sphere&quot;]&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log2p=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[(5,)]&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> visualize.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cases=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[&quot;sphere&quot;]&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log2p=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;[(5,)]&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=gpu/CUDA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --backend=CuArray</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # on an NVIDIA GPU</span></span></code></pre></div><p>Both take <code>--cases</code>, <code>--log2p</code> and <code>--ftype</code> as Julia lists, and <code>--data_dir</code> for the checkpoint directory (default <code>checkpoints/</code>).</p><h2 id="Adding-a-case" tabindex="-1">Adding a case <a class="header-anchor" href="#Adding-a-case" aria-label="Permalink to &quot;Adding a case {#Adding-a-case}&quot;">​</a></h2><ol><li><p>Add a function to <code>src/cases.jl</code> that returns the <code>Simulation</code>, named as the case with <code>-</code> replaced by <code>_</code> (the case <code>tgv-periodic</code> is the function <code>tgv_periodic</code>).</p></li><li><p>In <code>src/util.jl</code>, add the case to <code>all_cases</code>, and give it entries in <code>tests_dets</code> (the domain shape in units of <code>2^log2p</code>, for the cost per cell, and the plot title), <code>develop_time</code> and <code>checkpoint_log2p</code>. If the body moves, add it to <code>remeasure_case</code>.</p></li><li><p>Add the same default sizes to <code>DEF_LOG2P</code> at the top of <code>benchmark.sh</code>.</p></li><li><p>Make the checkpoints with <code>julia --project develop.jl --cases=&#39;[&quot;&lt;case&gt;&quot;]&#39;</code>, check them with <code>visualize.jl</code>, and commit them (git-LFS) with their images.</p></li></ol>`,14)])])}const F=t(g,[["render",y]]);export{x as __pageData,F as default};
